def compute_affine_iterative(w):
    slope, intercept = Fraction(1), Fraction(0)
    for b in reversed(w):
        if b:
            intercept = slope + intercept
            slope = 3 * slope
        else:
            slope = slope / 2
    return slope, intercept

def cycle_candidate(w):
    s, c = compute_affine_iterative(w)
    if s == 1: return None
    return c / (1 - s)

def valid_words(k):
    if k <= 0: return [[]]
    if k == 1: return [[False], [True]]
    result = []
    for w in valid_words(k-1):
        result.append(w + [False])
        if not w[-1]: result.append(w + [True])
    return result
